using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class InputFoundationChecks {
 public static void Run(){int n=0;Action<bool,string> c=(ok,name)=>{if(!ok)throw new Exception("FAIL "+name);n++;};
 for(int i=0;i<9;i++){var r=new ModifierPressOwnership();r.t1[i]=ModifiedInputAction.C;var f=r.Sample(1<<i,1<<i,false,false,true);c(f.attackMask==(1<<i),"normal immediate "+i);f=r.Sample(1<<i,0,true,false,true);c(f.attackMask==0&&f.pulses.SequenceEqual(new[]{ModifiedInputAction.C}),"late modifier emits new chord "+i);c(r.Sample(1<<i,0,true,false,true).pulses.Length==0,"held no repeat "+i);f=r.Sample(1<<i,0,false,false,true);c(f.attackMask==0&&f.pulses.Length==0,"release modifier no normal "+i);c(r.Sample(1<<i,0,true,false,true).pulses.Length==1,"reformation new edge "+i);r.Sample(0,0,true,false,true);c(r.Sample(1<<i,1<<i,true,false,true).pulses.Length==1,"face repress new chord "+i);var same=new ModifierPressOwnership();same.t1[i]=ModifiedInputAction.C;f=same.Sample(1<<i,1<<i,true,false,true);c(f.attackMask==0&&f.pulses.Length==1,"same tick chord only "+i);}
 var training=new ModifierPressOwnership();training.t1[0]=ModifiedInputAction.Record;var x=training.Sample(1,1,true,false,false);c(x.attackMask==0&&x.pulses.Length==0,"training inert outside mode");c(new ModifierPressOwnership().Sample(256,256,true,true,true).pulses.Length==0,"no invented double modifier action");var clear=new ModifierPressOwnership();clear.Sample(256,256,true,false,true);clear.Clear();c(clear.Sample(0,0,false,false,true).pulses.Length==0,"clear removes held state");string error;c(!ModifierPressOwnership.ValidateBindings("x","x",new string[0],out error),"modifier collision rejected");c(!ModifierPressOwnership.ValidateBindings("x","",new[]{"x"},out error),"modifier normal collision rejected");c(!ModifierPressOwnership.ValidateChords(new[]{"B:T1:slot","B:T1:slot"},out error),"duplicate chord rejected");var slots=CharacterAttackSlot.AwariDefaults();c(CharacterAttackSlot.Validate(slots,out error),"nine character slots valid");c(slots.Where(s=>s.slot==BattleAttackSlot.A||s.slot==BattleAttackSlot.B||s.slot==BattleAttackSlot.C).All(s=>!s.assigned),"ABC moves not invented");c(slots.Single(s=>s.slot==BattleAttackSlot.J).command==TrainingCommand.Light,"J maps LP");c(slots.Single(s=>s.slot==BattleAttackSlot.L).command==TrainingCommand.Heavy,"L maps HP");var result=n+" PASS, 0 FAIL (chord edge foundation)";var args=Environment.GetCommandLineArgs();int iarg=Array.IndexOf(args,"-inputFoundationReport");if(iarg>=0)File.WriteAllText(args[iarg+1],result);Debug.Log(result);PublicSnapshotChecks.Verify();}
}
